def compute(vars):
    sold_or_repledged = vars["v1"]
    collateral_usable = vars["v2"]

    if collateral_usable == 0:
        return None

    ratio = sold_or_repledged / collateral_usable
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "sold_or_repledged": sold_or_repledged,
            "collateral_usable": collateral_usable,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
